                "00000000-0000-0000-"
                "0000-000000000001"
            ),
            "a@example.com",
        )


def test_provider_failure_does_not_persist(
    monkeypatch,
):
    monkeypatch.setattr(
        repository,
        "session_exists_for_user",
        lambda *_args, **_kwargs: True,
    )

    saved = []

    monkeypatch.setattr(
        repository,
        "save_exchange",
        lambda **kwargs: saved.append(
            kwargs
        ),
    )

    async def fail_provider(
        *_args,
        **_kwargs,
    ):
        raise service.LLMTimeoutError(
            "timeout"
        )

    monkeypatch.setattr(
        service,
        "_send_llm",
        fail_provider,
    )

    with pytest.raises(
        service.LLMTimeoutError
    ):
        asyncio.run(
            service.enviar_mensaje(
                (
                    "00000000-0000-0000-"
                    "0000-000000000001"
                ),
                "a@example.com",
                "hola",
            )
        )

    assert saved == []


def test_success_persists_atomic_exchange(
    monkeypatch,
):
    monkeypatch.setattr(
        repository,
        "session_exists_for_user",
        lambda *_args, **_kwargs: True,
    )

    captured = {}

    def save_exchange(**kwargs):
        captured.update(kwargs)
        return True

    monkeypatch.setattr(
        repository,
        "save_exchange",
        save_exchange,
    )

    async def answer(
        *_args,
        **_kwargs,
    ):
        return "respuesta controlada"

    monkeypatch.setattr(
        service,
        "_send_llm",
        answer,
    )

    result = asyncio.run(
        service.enviar_mensaje(
            (
                "00000000-0000-0000-"
                "0000-000000000001"
            ),
            "a@example.com",
            "hola",
        )
    )

    assert (
        result["respuesta"]
        == "respuesta controlada"
    )

    assert (
        captured["user_text"]
        == "hola"
    )

    assert (
        captured["assistant_text"]
        == "respuesta controlada"
    )


